// Medimos cuánto tarda vaciar una cola de N elementos de dos maneras
function conShift(N) {
  const q = [];
  for (let i = 0; i < N; i++) q.push(i);
  const t0 = performance.now();
  let suma = 0;
  while (q.length) suma += q.shift();         // sacar del frente del array
  return performance.now() - t0;
}
function conCabeza(N) {
  const q = [];
  for (let i = 0; i < N; i++) q.push(i);
  const t0 = performance.now();
  let suma = 0, cabeza = 0;
  while (cabeza < q.length) suma += q[cabeza++]; // solo avanzamos un índice
  return performance.now() - t0;
}
conShift(1000); conCabeza(1000);              // calentamiento
for (const N of [10000, 30000, 60000]) {
  console.log(`N = ${String(N).padStart(6)}   shift(): ${conShift(N).toFixed(1).padStart(7)} ms   índice: ${conCabeza(N).toFixed(2).padStart(6)} ms`);
}

class Pila {
  #items = [];
  apilar(x) { this.#items.push(x); }
  desapilar() {
    if (this.vacia()) throw new Error("pila vacía");
    return this.#items.pop();
  }
  tope() {
    if (this.vacia()) throw new Error("pila vacía");
    return this.#items[this.#items.length - 1];
  }
  vacia() { return this.#items.length === 0; }
  get tamano() { return this.#items.length; }
}

class Cola {
  #items = [];
  #cabeza = 0;                       // posición del primero que sigue en salir
  encolar(x) { this.#items.push(x); }
  desencolar() {
    if (this.vacia()) throw new Error("cola vacía");
    const x = this.#items[this.#cabeza];
    this.#items[this.#cabeza] = undefined;   // soltamos la referencia
    this.#cabeza++;
    // cuando más de la mitad del array es espacio ya usado, lo compactamos
    if (this.#cabeza >= 32 && this.#cabeza * 2 >= this.#items.length) {
      this.#items = this.#items.slice(this.#cabeza);
      this.#cabeza = 0;
    }
    return x;
  }
  frente() {
    if (this.vacia()) throw new Error("cola vacía");
    return this.#items[this.#cabeza];
  }
  vacia() { return this.tamano === 0; }
  get tamano() { return this.#items.length - this.#cabeza; }
}

