// Cola circular con tope: cuando se llena, la entrada nueva desplaza a la más vieja
class ColaAcotada {
  constructor(tope) {
    this.tope = tope;
    this.celdas = new Array(tope);   // tamaño fijo, no crece nunca
    this.cabeza = 0;                 // dónde está el más viejo
    this.n = 0;                      // cuántos hay
    this.descartados = 0;
  }
  encolar(x) {
    if (this.n === this.tope) {      // llena: pisamos al más viejo y la cabeza avanza
      this.celdas[this.cabeza] = x;
      this.cabeza = (this.cabeza + 1) % this.tope;
      this.descartados++;
    } else {
      this.celdas[(this.cabeza + this.n) % this.tope] = x;
      this.n++;
    }
  }
  desencolar() {
    if (this.n === 0) return undefined;
    const x = this.celdas[this.cabeza];
    this.celdas[this.cabeza] = undefined;
    this.cabeza = (this.cabeza + 1) % this.tope;
    this.n--;
    return x;
  }
  aArray() { return Array.from({ length: this.n }, (_, i) => this.celdas[(this.cabeza + i) % this.tope]); }
}

const c = new ColaAcotada(5);
