// 2) La misma suma 1 + 2 + ... + n, recursiva (usa la pila de llamadas)...
function sumaRecursiva(n) { return n === 0 ? 0 : n + sumaRecursiva(n - 1); }
// ...y con una pila nuestra, que vive en la memoria común y crece cuanto haga falta
function sumaConPila(n) {
  const pendientes = [];                 // lo que antes dejaba apilado el motor
  for (let k = n; k > 0; k--) pendientes.push(k);
  let total = 0;
  while (pendientes.length) total += pendientes.pop();
  return total;
}

