const PARES = { ")": "(", "]": "[", "}": "{" };

function balanceado(texto) {
  const pila = [];
  for (const ch of texto) {
    if (ch === "(" || ch === "[" || ch === "{") {
      pila.push(ch);                              // abre: lo dejamos pendiente
    } else if (ch in PARES) {
      if (pila.pop() !== PARES[ch]) return false; // cierra: tiene que coincidir con el último que abrió
    }
  }
  return pila.length === 0;                       // no puede quedar nada abierto
}

