// Un muelle con una sola dársena. Cada camión llega en cierto minuto y tarda cierto tiempo en cargarse.
const camiones = [
  { nombre: "A", llega: 0, carga: 8 },
  { nombre: "B", llega: 1, carga: 3 },
  { nombre: "C", llega: 2, carga: 5 },
  { nombre: "D", llega: 3, carga: 2 },
  { nombre: "E", llega: 4, carga: 4 },
  { nombre: "F", llega: 6, carga: 1 },
  { nombre: "G", llega: 20, carga: 3 },
];

function simular(camiones, politica) {
  const fila = [];                        // los camiones esperando
  const resultado = [];
  let reloj = 0, proximo = 0;
  while (proximo < camiones.length || fila.length) {
    while (proximo < camiones.length && camiones[proximo].llega <= reloj) fila.push(camiones[proximo++]);
    if (!fila.length) { reloj = camiones[proximo].llega; continue; }   // dársena vacía: esperamos al próximo
    const c = politica === "FIFO" ? fila.shift() : fila.pop();         // acá está toda la diferencia
    resultado.push({ nombre: c.nombre, espera: reloj - c.llega });
    reloj += c.carga;
  }
  return resultado;
}

for (const politica of ["FIFO", "LIFO"]) {
  const r = simular(camiones, politica);
  const esperas = r.map(x => x.espera);
  const promedio = esperas.reduce((a, b) => a + b, 0) / esperas.length;
  console.log(`${politica}: orden ${r.map(x => x.nombre).join("")} · esperas ${esperas.join(",")} · promedio ${promedio.toFixed(1)} min · máxima ${Math.max(...esperas)} min`);
}

// La política de la bandeja de Senda, reescrita con fines didácticos:
// tope 500, lotes de 50, y al mandar un lote se saca recién cuando el servidor confirmó.
const TOPE = 500, LOTE = 50;
let bandeja = [];
for (let i = 1; i <= 700; i++) {           // 700 respuestas sin señal
  bandeja.push(i);
  if (bandeja.length > TOPE) bandeja = bandeja.slice(-TOPE);   // se pierden las más viejas
}
console.log(`sin señal: 700 anotadas, quedan ${bandeja.length} (de la ${bandeja[0]} a la ${bandeja[bandeja.length - 1]})`);

let lotes = 0, fallaUnaVez = true;
function mandar(lote) {                    // el «servidor»: el primer intento se corta
  if (fallaUnaVez) { fallaUnaVez = false; return false; }
  return true;
}
while (bandeja.length) {
  const lote = bandeja.slice(0, LOTE);     // mirar el frente sin sacar nada todavía
  if (!mandar(lote)) { console.log("falló el envío: el lote sigue en la bandeja"); continue; }
  bandeja = bandeja.slice(lote.length);    // confirmado: ahora sí se saca
  lotes++;
}
console.log("con señal otra vez: se mandaron", lotes, "lotes de", LOTE);
